func (c *Core) cdladvanceblockOpenAndFillInternal(inOpen, inHigh, inLow, inClose []float64, startIdx int32, outBegIdx, outNBElement *int32, outInteger []int32) (*CDLADVANCEBLOCKStream, error) {
	sp := &CDLADVANCEBLOCKStream{core: c}
	if retCode := c.cdladvanceblockOpenImpl(sp, inOpen, inHigh, inLow, inClose, startIdx, outBegIdx, outNBElement, outInteger, 1); retCode != Success {
		return nil, retCode
	}
	sp.outRangeBegIdx = int(*outBegIdx)
	sp.outRangeCount = int(*outNBElement)
	return sp, nil
}

func (c *Core) cdladvanceblockOpenInternal(inOpen, inHigh, inLow, inClose []float64, startIdx int32) (*CDLADVANCEBLOCKStream, error) {
	sp := &CDLADVANCEBLOCKStream{core: c}
	var outBegIdx, outNBElement int32
	var sink_outInteger [1]int32
	if retCode := c.cdladvanceblockOpenImpl(sp, inOpen, inHigh, inLow, inClose, startIdx, &outBegIdx, &outNBElement, sink_outInteger[:], 0); retCode != Success {
		return nil, retCode
	}
	sp.outRangeBegIdx = int(outBegIdx)
	sp.outRangeCount = int(outNBElement)
	return sp, nil
}

// CDLADVANCEBLOCKOpen opens a live [CDLADVANCEBLOCKStream] on a warm-up
// history, oldest bar first, and returns it with its value at the last history
// bar, the value [Core.CDLADVANCEBLOCK] writes there.
//
// inOpen, inHigh, inLow and inClose are the histories, of one length.
//
// The error is [InsufficientHistory] for a history of at most
// [Core.CDLADVANCEBLOCKLookback] bars, and [BadParam] for histories of
// different lengths.
func (c *Core) CDLADVANCEBLOCKOpen(inOpen, inHigh, inLow, inClose []float64) (*CDLADVANCEBLOCKStream, int32, error) {
	sp, err := c.cdladvanceblockOpenInternal(inOpen, inHigh, inLow, inClose, 0)
	if err != nil {
		return nil, 0, err
	}
	return sp, sp.cur_outInteger, nil
}

// CDLADVANCEBLOCKOpenAndFill opens a stream as [Core.CDLADVANCEBLOCKOpen] does
// and also writes the outputs over the whole history, as [Core.CDLADVANCEBLOCK]
// writes them for bars 0 through len(inOpen)-1, returning that range.
//
// Each output must hold len(inOpen) minus [Core.CDLADVANCEBLOCKLookback] values
// and share no memory with an input or another output.
//
// The errors are those of [Core.CDLADVANCEBLOCKOpen], and [BadParam] for an
// output that is empty, too short or sharing memory.
func (c *Core) CDLADVANCEBLOCKOpenAndFill(inOpen, inHigh, inLow, inClose []float64, outInteger []int32) (*CDLADVANCEBLOCKStream, OutRange, error) {
	if len(inOpen) > IndexMax+1 {
		return nil, OutRange{}, OutOfRangeEndIndex
	}
	lookback := int(c.cdladvanceblockLookback())
	if lookback < 0 {
		return nil, OutRange{}, BadParam
	}
	if len(inHigh) != len(inOpen) {
		return nil, OutRange{}, BadParam
	}
	if len(inLow) != len(inOpen) {
		return nil, OutRange{}, BadParam
	}
	if len(inClose) != len(inOpen) {
		return nil, OutRange{}, BadParam
	}
	outLen := max(len(inOpen)-lookback, 0)
	if len(outInteger) == 0 || len(outInteger) < outLen {
		return nil, OutRange{}, BadParam
	}
	var outBegIdx, outNBElement int32
	sp, err := c.cdladvanceblockOpenAndFillInternal(inOpen, inHigh, inLow, inClose, 0, &outBegIdx, &outNBElement, outInteger)
	if err != nil {
		return nil, OutRange{}, err
	}
	return sp, OutRange{BegIdx: int(outBegIdx), NBElement: int(outNBElement)}, nil
}
